import argparse
import csv
import json
from pathlib import Path


def total(path):
    items = json.load(open(path))
    return sum(i["qty"] * i["price"] for i in items)


def export_csv(path: str) -> Path:
    items = json.load(open(path))
    fields = list(dict.fromkeys(k for i in items for k in i))
    out = Path(path).with_suffix(".csv")
    with out.open("w", newline="") as f:
        writer = csv.DictWriter(f, fields)
        writer.writeheader()
        writer.writerows(items)
    return out


if __name__ == "__main__":
    parser = argparse.ArgumentParser(prog="invoice.py")
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("total").add_argument("file")
    export = commands.add_parser("export")
    export.add_argument("--csv", action="store_true", required=True)
    export.add_argument("file")
    args = parser.parse_args()
    if args.command == "total":
        print(total(args.file))
    else:
        print(export_csv(args.file))
